# -*- coding: utf-8 -*-
import json, os, re, io

ROOT = r"D:/repository"
CACHE = r"C:/Users/Administrator/.dsh/cache/memory-audit"
d = json.load(open(CACHE + "/select.json", encoding="utf-8"))

SKIP = {"node_modules", ".git", "dist", "build", ".task-state", "coverage", "test-results"}
EXTS = {".vue", ".js", ".ts", ".jsx", ".tsx", ".json", ".mjs", ".scss", ".css", ".md", ".py", ".html"}

# build basename index once
index = {}
proj_dirs = []
for dirpath, dirnames, filenames in os.walk(ROOT):
    dirnames[:] = [x for x in dirnames if x not in SKIP]
    rel = os.path.relpath(dirpath, ROOT).replace("\\", "/")
    depth = 0 if rel == "." else rel.count("/") + 1
    if depth <= 1 and rel != ".":
        proj_dirs.append(rel)
    if depth > 5:
        continue
    for fn in filenames:
        ext = os.path.splitext(fn)[1].lower()
        if ext not in EXTS:
            continue
        index.setdefault(fn, []).append(os.path.join(dirpath, fn).replace("\\", "/"))

def match_proj(pname):
    if not pname:
        return []
    p = pname.strip()
    out = []
    for pd in proj_dirs:
        base = pd.split("/")[-1]
        if p == base or p in base or base in p:
            out.append(pd)
    return out[:4]

def tokens_of(content):
    toks = set()
    for m in re.findall(r"/[A-Za-z][A-Za-z0-9_\-/]{3,}", content):
        if m.count("/") >= 2 and len(m) > 6:
            toks.add(m.rstrip("/"))
    for m in re.findall(r"\b[a-z][a-zA-Z0-9]{6,}\b", content):
        toks.add(m)
    for m in re.findall(r"\b[A-Z][A-Z0-9_]{4,}\b", content):
        toks.add(m)
    stop = {"verification", "extracted", "session", "baseline", "project", "source",
            "涉及文件", "所属项目", "来源会话", "代码基线", "验证证据"}
    toks = [t for t in toks if t not in stop and not t.startswith("http")]
    # prefer distinctive: file-derived + long
    return sorted(toks, key=lambda x: (-len(x), x))[:14]

def read_text(path):
    try:
        with open(path, encoding="utf-8", errors="ignore") as f:
            return f.read()
    except Exception:
        return ""

out = io.open(CACHE + "/_evidence.txt", "w", encoding="utf-8")
for i, c in enumerate(d["candidates"]):
    content = c["content"]
    pm = re.search(r"所属项目[：:]\s*([^\n;；]+)", content)
    pname = pm.group(1).strip() if pm else ""
    fm = re.search(r"涉及文件[：:]\s*([^\n]+)", content)
    files = []
    if fm:
        for part in re.split(r"[、,，;；]", fm.group(1)):
            part = part.strip().strip("`").replace("\\", "/")
            bn = part.split("/")[-1].strip()
            if bn and "." in bn:
                files.append(bn)
    pds = match_proj(pname)
    # file existence
    found, missing = [], []
    for bn in files:
        hits = index.get(bn, [])
        if hits:
            found.append(bn + "@" + "/".join(hits[0].split("/")[3:5]))
        else:
            missing.append(bn)
    # token hits within matched project dirs (or whole repo if no project matched)
    toks = tokens_of(content)
    hits, misses = [], []
    scope = []
    base = ROOT.replace("\\", "/")
    for pd in (pds if pds else [""]):
        for bnset in (files or []):
            for p in index.get(bnset, []):
                if pd and (pd + "/") in p:
                    scope.append(p)
        if not files:
            for p in index.values():
                pass
    scope = list(dict.fromkeys(scope))[:40]
    texts = [read_text(p) for p in scope]
    blob = "\n".join(texts)
    for t in toks:
        (hits if t in blob else misses).append(t)
    out.write("=== %02d %s %s\n" % (i, c["body_sha256_16"], c["uri"].split("/")[-1]))
    out.write("PROJ=%s DIRS=%s\n" % (pname, ",".join(pds)))
    out.write("FILES_FOUND=%s\n" % (",".join(found[:12]) or "-"))
    out.write("FILES_MISSING=%s\n" % (",".join(missing[:12]) or "-"))
    out.write("TOK_HIT=%s\n" % (",".join(hits[:12]) or "-"))
    out.write("TOK_MISS=%s\n" % (",".join(misses[:12]) or "-"))
    out.write("\n")
out.close()
print("evidence written, proj_dirs=%d, index=%d" % (len(proj_dirs), len(index)))

